+        if p.len() != q.len() || p.is_empty() {
+            return 0.0;
+        }
+        let eps = 1e-12;
+        -p.iter()
+            .zip(q.iter())
+            .map(|(&pi, &qi)| {
+                let pi_c = pi.max(eps);
+                let qi_c = qi.max(eps);
+                pi_c * qi_c.ln()
+            })
+            .sum::<f64>()
+    }
